<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Online Metronome','description'=>'Keep a steady beat with an adjustable BPM metronome.','url'=>'https://smarttoolz.in/tools/metronome/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><h1>Metronome</h1><p>Set BPM and keep a steady beat.</p></section><section class="tool-workspace"><div class="tool-panel"><label>BPM<input id="b" type="number" min="20" max="240" value="80"></label><button id="go" class="tool-btn">Start</button><div id="o" style="font-size:32px;font-weight:800">●</div></div></section></main><script>let id=0;go.onclick=()=>{if(id){clearInterval(id);id=0;go.textContent='Start';return}let f=()=>{o.textContent='●';setTimeout(()=>o.textContent='○',100)};f();id=setInterval(f,60000/+b.value);go.textContent='Stop'}</script><?php smarttoolz_tool_page_end(); ?>